# Trial balance (start_date, end_date in YYYY-MM-DD format)
start_date = 'YYYY-MM-DD'
end_date = 'YYYY-MM-DD'
domain = [
    ('move_id.state', '=', 'posted'),
    ('date', '>=', start_date),
    ('date', '<=', end_date),
    ('account_id', '!=', False),
]
lines = env['account.move.line'].search(domain)
by_account = {}
for line in lines:
    acc = line.account_id
    if acc:
        aid = acc.id
        if aid not in by_account:
            by_account[aid] = {'debit': 0, 'credit': 0, 'account': acc}
        by_account[aid]['debit'] += line.debit
        by_account[aid]['credit'] += line.credit
result = []
for data in by_account.values():
    acc = data['account']
    result.append({
        'codigo': acc.code or '',
        'cuenta': acc.name or '',
        'debe': data['debit'],
        'haber': data['credit'],
        'saldo': data['debit'] - data['credit']
    })
result = sorted(result, key=operator.itemgetter('codigo'))

digits_level = 2
start_date = 'YYYY-MM-DD'
end_date = 'YYYY-MM-DD'
domain = [
    ('move_id.state', '=', 'posted'),
    ('date', '>=', start_date),
    ('date', '<=', end_date),
    ('account_id', '!=', False),
]
lines = env['account.move.line'].search(domain)

by_prefix = {}
for line in lines:
    acc = line.account_id
    if acc and acc.code:
        # Extraer el substring exacto por el nivel de dígitos
        prefix = acc.code[:digits_level]
        if prefix not in by_prefix:
            by_prefix[prefix] = {'debit': 0, 'credit': 0}

        by_prefix[prefix]['debit'] += line.debit
        by_prefix[prefix]['credit'] += line.credit

result = []
for prefix, data in by_prefix.items():
    result.append({
        'codigo': prefix,
        'cuenta': 'Grupo ' + prefix,
        'debe': data['debit'],
        'haber': data['credit'],
        'saldo': data['debit'] - data['credit']
    })
result = sorted(result, key=operator.itemgetter('codigo'))
